// C++14 feature
#include <deque>

// A function that should return a reference to a container element.
// NOTE: This implementation is INCORRECT because 'auto' strips the reference.
template<typename Container, typename Index>
auto accessElement_WRONG(Container& c, Index i)
{
  return c[i]; // c[i] returns int&, but function returns int
}

int main() {
  std::deque<int> d = {1, 2, 3, 4, 5};
  // accessElement_WRONG(d, 2) = 42; // COMPILE ERROR!
  // Error: expression is not assignable because the function returns a temporary rvalue (int), not a reference (int&).
  return 0;
}
